  // Pause -> flip around Y axis -> reveal Q02 at SAME pivot/scale -> settle.
  const x=500,y=322,size=1.13;
  const dt=Math.max(0,sec-94.097);
  const pause=.12,duration=.46;
  const f=clamp((dt-pause)/duration,0,1);
