  const sx=Math.max(.025,Math.abs(Math.cos(turning*Math.PI)));
  const code=dt<pause||turning<.5?'Q04':'Q02';
  ctx.save();ctx.translate(x,0);ctx.scale(sx,1);ctx.translate(-x,0);
  drawQCharacter(code,x,y,size,sec,{still:true,noTalkBars:true});
  ctx.restore();
