 const appear=smooth(progress/.22)*smooth((1-progress)/.20);
 const caption=e.short_label;
 if(!caption||caption==='—')return;
 ctx.save();ctx.globalAlpha=.81*appear;
 let x=e.placement==='left_edge'?35: e.placement==='upper_right'?660:705; if(shot.character.includes('正常')&&shot.character.includes('Q')&&x>700)x=38;
 let y=e.placement==='upper_right'?88:334;
 // Do not crowd Q face or the standard top-left storyboard info panel.
 const w=Math.min(235,Math.max(116,caption.length*11+32));
 ctx.translate(x+(1-appear)*15,y);ctx.fillStyle='#161934d9';ctx.strokeStyle='#c5acffbd';ctx.lineWidth=2;
 rounded(0,0,w,44,7);ctx.fill();ctx.stroke();
