const CG01_MONTAGE_CACHE=document.createElement('canvas');
CG01_MONTAGE_CACHE.width=960;CG01_MONTAGE_CACHE.height=540;
const CG01_MONTAGE_CTX=CG01_MONTAGE_CACHE.getContext('2d');
function cg01Montage(sec, images, g, cfg={}) {
 const A=4.151,B=7.168,C=11.035,D=14.907;
 const sat=n=>Math.max(0,Math.min(1,n));
 const ease=n=>{const x=sat(n);return x*x*(3-2*x)};
 const crossStart=C-.24,crossEnd=C+.28;
 const cross=ease((sec-crossStart)/(crossEnd-crossStart));
 const endZoom=cfg.endZoom??1.025;
 g.save();g.fillStyle='#020209';g.fillRect(0,0,960,540);
 function draw(img,alpha=1,zoom=1,filter='none',ox=480,oy=270){
   if(!img||!img.complete||!img.naturalWidth||alpha<=0)return;
   g.save();g.globalAlpha=sat(alpha);g.filter=filter;
   g.drawImage(img,-ox*(zoom-1),-oy*(zoom-1),960*zoom,540*zoom);g.restore();
 }
 if(sec<B){
   const t=sec-A;
   const a=t<.60?ease(t/.60):(t<1.52?1:1-ease((t-1.52)/1.20));
   const radius=(cfg.faceRadius||222)*(.94+.06*ease(t));
   if(a>.0001&&images.S003?.complete){
     const x=485,y=235,cg=CG01_MONTAGE_CTX;
     cg.clearRect(0,0,960,540);
     cg.save();cg.filter='brightness(1.13) saturate(1.08)';cg.drawImage(images.S003,0,0,960,540);cg.restore();
     cg.save();cg.globalCompositeOperation='destination-in';
     const grad=cg.createRadialGradient(x,y,3,x,y,radius);
     grad.addColorStop(0,`rgba(255,255,255,${a})`);
     grad.addColorStop(.27,`rgba(255,255,255,${a*.98})`);
     grad.addColorStop(.68,`rgba(255,255,255,${a*.63})`);
     grad.addColorStop(1,'rgba(255,255,255,0)');
     cg.fillStyle=grad;cg.fillRect(0,0,960,540);cg.restore();
     g.drawImage(CG01_MONTAGE_CACHE,0,0);
     const glow=g.createRadialGradient(x,y,3,x,y,radius*1.08);
     glow.addColorStop(0,`rgba(223,204,255,${a*.105})`);
     glow.addColorStop(.35,`rgba(170,140,255,${a*.045})`);
     glow.addColorStop(1,'rgba(120,100,220,0)');
     g.fillStyle=glow;g.fillRect(0,0,960,540);
   }
 }
 else if(sec<C){
   const t=sec-B,e=t-(cfg.flashOnset??.55);
   if(e>=-.20){
     const pre=e<0?ease((e+.20)/.20):1;
     const level=e<0?pre*.34:(.08+.92*Math.exp(-Math.max(0,e)/1.02));
     const hold=.165*ease((sec-(C-.9))/.62);
     const a=Math.max(level,hold)*(1-cross);
     if(e>=0&&e<.42)draw(images.S004,.20*(1-e/.42)*(1-cross),1.022,'blur(5px)');
     draw(images.S004,a,1+.008*ease((e+.15)/2),'brightness(1.1)');
     if(e>=0&&e<.105){g.fillStyle=`rgba(244,232,255,${.14*(1-e/.105)})`;g.fillRect(0,0,960,540);}
   }
   // The S005 frame already begins to dissolve in during the final 0.24s of S004.
   if(cross>0)draw(images.S005,cross,1,'none',675,266);
 }
 else if(sec<D){
   const t=sec-C;
   // Keep the S004 afterimage alive briefly across the shot boundary.
   if(cross<1)draw(images.S004,.165*(1-cross),1.008,'brightness(1.1)');
   const zoom=1+(endZoom-1)*ease(t/3.80);
   draw(images.S005,cross,zoom,'none',675,266);
   if(cross>.01){
      const shimmer=Math.max(0,1-t/1.0)*.043;
      g.fillStyle=`rgba(226,208,255,${shimmer*cross})`;
      g.fillRect(0,0,960,540);
   }
 }
 g.restore();
}

// S005 -> S006: UI power-on wipes in over the outgoing close-up, actual S006 scene below.
const cg01BootBuffer=document.createElement('canvas');
cg01BootBuffer.width=960;cg01BootBuffer.height=540;
const cg01BootCtx=cg01BootBuffer.getContext('2d');
function cg01BootTransition(sec){
 const start=14.907,t=sec-start;
 if(t<0||t>.72)return;
 const easing=n=>{let x=clamp(n,0,1);return x*x*(3-2*x)};
 cg01BootCtx.clearRect(0,0,W,H);
 cg01BootCtx.drawImage(ctx.canvas,0,0,W,H);
 ctx.save();ctx.fillStyle='#020309';ctx.fillRect(0,0,W,H);
 // At t=0 the last CG is already fully dark. Never redraw the bright source CG.
 const open=easing((t-.055)/.55), height=H*open;
 if(open>.001){
   ctx.save();ctx.beginPath();ctx.rect(0,H/2-height/2,W,height);ctx.clip();
   ctx.drawImage(cg01BootBuffer,0,0,W,H);
   const scan=.13*(1-easing(t/.59));
   if(scan>.003){ctx.fillStyle='rgba(7,9,28,'+scan+')';for(let y=0;y<H;y+=5)ctx.fillRect(0,y,W,1)}
   ctx.restore();
 }
 const glow=(1-open)*(.42*easing(t/.16));
 if(glow>.004){ctx.save();ctx.globalCompositeOperation='screen';
  const g=ctx.createLinearGradient(0,H/2-9,0,H/2+9);
  g.addColorStop(0,'rgba(205,173,255,0)');g.addColorStop(.5,'rgba(237,217,255,'+glow+')');g.addColorStop(1,'rgba(205,173,255,0)');
  ctx.fillStyle=g;ctx.fillRect(0,H/2-9,W,18);ctx.restore();}
 ctx.restore();
}


