 const currMode=assignment[shot.id]?.render_mode;
 const newFrame=currMode==='FRAME' && prevMode!=='FRAME' && !['S072','S073','S074'].includes(shot.id);
 const workOpen=sec>=17.458 && sec<18.18;
 if(!newFrame && !workOpen)return;
 const age=workOpen?sec-17.458:sec-shot.start;
 if(age<0||age>.76)return;
 const appear=v31Ease(0,.20,age),disappear=1-v31Ease(.52,.76,age),a=appear*disappear;
 const items=[[911,122,1],[878,405,5],[617,53,9]];
